            float g01 = fmaf(st.z, acc[m][n][1], fmaf(-st.w, uv0.x, uv0.y));
            float g10 = fmaf(st.x, acc[m][n][2], fmaf(-st.y, uv1.x, uv1.y));
            float g11 = fmaf(st.z, acc[m][n][3], fmaf(-st.w, uv1.x, uv1.y));
