    const float* pp = p.part + (size_t)b * TPI * C4 + k;
    float s[8] = {0.f, 0.f, 0.f, 0.f, 0.f, 0.f, 0.f, 0.f};
    int r = 0;
    for (; r + 8 <= TPI; r += 8) {
#pragma unroll
      for (int u = 0; u < 8; u++) s[u] += __ldcg(pp + (size_t)(r + u) * C4);
    }
    for (; r < TPI; r++) s[0] += __ldcg(pp + (size_t)r * C4);
