            ts.append(harness_time(f, ins, [out]))
        print((B,C,H,W),'variant',v,'maxerr %.3e bad %d'%(err.max().item(),bad), 'cum us K0/+P1/+K3/+G2', ['%.1f'%t for t in ts]); del r, err
